 isupKey: 12345678\n\n  # 报警服务器打印事件模式\n  # file=事件保存到文件中\n  # console=事件打印在控制台上\n  eventInfoPrintType: console\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'海康isup生成接口文档\'\n    # 描述\n    description: \'海康isup生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '56446de72512f79abab35a9a2bd40b90', '2026-03-28 16:00:45', '2026-03-28 16:33:05', 'nacos', '172.19.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
