INSERT INTO `config_info` VALUES (35, 'ruoyi-zlm-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  gateway:\n    prrt: 8080\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.zlm.**.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# [根据业务需求配置]\nuser-settings:\n  # 点播/录像回放 等待超时时间,单位：毫秒\n  play-timeout: 180000\n  # [可选] 自动点播， 使用固定流地址进行播放时，如果未点播则自动进行点播, 需要rtp.enable=true\n  auto-apply-play: true\n  # 推流直播是否录制\n  record-push-live: true\n  # 国标是否录制\n  record-sip: true\n  # 国标点播 按需拉流, true：有人观看拉流，无人观看释放， false：拉起后不自动释放\n  stream-on-demand: false\n  # 是否返回Date属性，true：不返回，避免摄像头通过该参数自动校时，false：返回，摄像头可能会根据该时间校时\n  disable-date-header: false\n  # 是否开启sql日志\n  sql-log: false\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'zlm生成接口文档\'\n    # 描述\n    description: \'zlm生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '918ed0955f6ba92a2452aec6d0d718d0', '2026-03-31 16:04:27', '2026-04-02 17:01:59', 'nacos_namespace_migrate', '172.19.0.1', '', '', '', NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` VALUES (36, 'ruoyi-zlm-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  gateway:\n    prrt: 8080\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.zlm.**.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# [根据业务需求配置]\nuser-settings:\n  # 点播/录像回放 等待超时时间,单位：毫秒\n  play-timeout: 180000\n  # [可选] 自动点播， 使用固定流地址进行播放时，如果未点播则自动进行点播, 需要rtp.enable=true\n  auto-apply-play: true\n  # 推流直播是否录制\n  record-push-live: true\n  # 国标是否录制\n  record-sip: true\n  # 国标点播 按需拉流, true：有人观看拉流，无人观看释放， false：拉起后不自动释放\n  stream-on-demand: false\n  # 是否返回Date属性，true：不返回，避免摄像头通过该参数自动校时，false：返回，摄像头可能会根据该时间校时\n  disable-date-header: false\n  # 是否开启sql日志\n  sql-log: false\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'zlm生成接口文档\'\n    # 描述\n    description: \'zlm生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '918ed0955f6ba92a2452aec6d0d718d0', '2026-03-31 16:04:27', '2026-04-02 17:01:59', 'nacos', '172.19.0.1', '', 'public', '', NULL, NULL, 'yaml', NULL, '');
