INSERT INTO `his_config_info` VALUES (36, 39, 'ruoyi-zlm-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.zlm.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n#zlm 默认服务器配置\nmedia:\n  id: hxkj_zlm\n  # [必须修改] zlm服务器的内网IP\n  ip: 192.168.2.200\n  # [必须修改] zlm服务器的http.port\n  http-port: 8092\n  http-ssl-port: 443\n  # [可选] zlm服务器的hook所使用的IP, 默认使用sip.ip\n  hook-ip: 192.168.2.200\n  # [必选选] zlm服务器的hook.admin_params=secret\n  secret: hxkj_zlm\n  #  # [可选] 录像文件存储路径\n  #  record-path: F:/zml/record\n  # [可选] 录像保存时间,单位是天\n  record-day: 3\n  # 启用多端口模式, 多端口模式使用端口区分每路流，兼容性更好。 单端口使用流的ssrc区分， 点播超时建议使用多端口测试\n  rtp:\n    # [可选] 是否启用多端口模式, 开启后会在portRange范围内选择端口用于媒体流传输\n    enable: true\n    # [可选] 在此范围内选择端口用于媒体流传输, 必须提前在zlm上配置该属性，不然自动配置此属性可能不成功\n    port-range: 30500,40500 # 端口范围\n    # [可选] 国标级联在此范围内选择端口发送媒体流,\n    send-port-range: 30000,30500 # 端口范围\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'zlm生成接口文档\'\n    # 描述\n    description: \'zlm生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', 'd2200439b01e5b4968e0a370cc0374c2', '2026-03-31 16:19:19', '2026-03-31 08:19:20', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
