INSERT INTO `his_config_info` VALUES (36, 43, 'ruoyi-zlm-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.zlm.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n#zlm 默认服务器配置\nmedia:\n  id: hxkj_zlm\n  # [必须修改] zlm服务器的内网IP\n  ip: 192.168.2.200\n  # [必须修改] zlm服务器的http.port\n  http-port: 8092\n  http-ssl-port: 443\n  # [可选] zlm服务器的hook所使用的IP, 默认使用sip.ip\n  hook-ip: 192.168.2.200\n  # [必选选] zlm服务器的hook.admin_params=secret\n  secret: hxkj_zlm\n  #  # [可选] 录像文件存储路径\n  #  record-path: F:/zml/record\n  # [可选] 录像保存时间,单位是天\n  record-day: 3\n  # 启用多端口模式, 多端口模式使用端口区分每路流，兼容性更好。 单端口使用流的ssrc区分， 点播超时建议使用多端口测试\n  rtp:\n    # [可选] 是否启用多端口模式, 开启后会在portRange范围内选择端口用于媒体流传输\n    enable: true\n    # [可选] 在此范围内选择端口用于媒体流传输, 必须提前在zlm上配置该属性，不然自动配置此属性可能不成功\n    port-range: 30500,40500 # 端口范围\n    # [可选] 国标级联在此范围内选择端口发送媒体流,\n    send-port-range: 30000,30500 # 端口范围\n\n# [根据业务需求配置]\nuser-settings:\n  # 点播/录像回放 等待超时时间,单位：毫秒\n  play-timeout: 180000\n  # [可选] 自动点播， 使用固定流地址进行播放时，如果未点播则自动进行点播, 需要rtp.enable=true\n  auto-apply-play: true\n  # 推流直播是否录制\n  record-push-live: true\n  # 国标是否录制\n  record-sip: true\n  # 国标点播 按需拉流, true：有人观看拉流，无人观看释放， false：拉起后不自动释放\n  stream-on-demand: false\n  # 是否返回Date属性，true：不返回，避免摄像头通过该参数自动校时，false：返回，摄像头可能会根据该时间校时\n  disable-date-header: false\n  # 是否开启sql日志\n  sql-log: false\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'zlm生成接口文档\'\n    # 描述\n    description: \'zlm生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', 'a0fa1887e39312c2c603ac5e1b0cf730', '2026-03-31 22:08:06', '2026-03-31 14:08:06', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (11, 44, 'ruoyi-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                # 验证码处理\n                - CacheRequestBody\n                - ValidateCodeFilter\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/code/**\n              filters:\n                - StripPrefix=1\n            # 定时任务\n            - id: ruoyi-job\n              uri: lb://ruoyi-job\n              predicates:\n                - Path=/schedule/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**\n              filters:\n                - StripPrefix=1\n            # 文件服务\n            - id: ruoyi-file\n              uri: lb://ruoyi-file\n              predicates:\n                - Path=/file/**\n              filters:\n                - StripPrefix=1\n             # 海康sdk服务\n            - id: ruoyi-haikang\n              uri: lb://ruoyi-haikang\n              predicates:\n                - Path=/haikang/**\n              filters:\n                - StripPrefix=1\n              # 泉视服务\n            - id: ruoyi-qs\n              uri: lb://ruoyi-qs\n              predicates:\n                - Path=/qs/**\n              filters:\n                - StripPrefix=1\n              # 海康isup服务\n            - id: ruoyi-haikang-isup\n              uri: lb://ruoyi-haikang-isup\n              predicates:\n                - Path=/haikangIsup/**\n              filters:\n                - StripPrefix=1\n              # 大华sdk服务\n            - id: ruoyi-dahua\n              uri: lb://ruoyi-dahua\n              predicates:\n                - Path=/dahua/**\n              filters:\n                - StripPrefix=1\n              # zlm服务\n            - id: ruoyi-zlm\n              uri: lb://ruoyi-zlm\n              predicates:\n                - Path=/zlm/**\n              filters:\n                - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', '3027bde0e2da528b650ab6467d0b0ae3', '2026-03-31 22:09:49', '2026-03-31 14:09:49', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
INSERT INTO `his_config_info` VALUES (36, 45, 'ruoyi-zlm-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  gateway:\n    prrt: 8080\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.zlm.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n#zlm 默认服务器配置\nmedia:\n  id: hxkj_zlm\n  # [必须修改] zlm服务器的内网IP\n  ip: 192.168.2.200\n  # [必须修改] zlm服务器的http.port\n  http-port: 8092\n  http-ssl-port: 443\n  # [可选] zlm服务器的hook所使用的IP, 默认使用sip.ip\n  hook-ip: 192.168.2.200\n  # [必选选] zlm服务器的hook.admin_params=secret\n  secret: hxkj_zlm\n  #  # [可选] 录像文件存储路径\n  #  record-path: F:/zml/record\n  # [可选] 录像保存时间,单位是天\n  record-day: 3\n  # 启用多端口模式, 多端口模式使用端口区分每路流，兼容性更好。 单端口使用流的ssrc区分， 点播超时建议使用多端口测试\n  rtp:\n    # [可选] 是否启用多端口模式, 开启后会在portRange范围内选择端口用于媒体流传输\n    enable: true\n    # [可选] 在此范围内选择端口用于媒体流传输, 必须提前在zlm上配置该属性，不然自动配置此属性可能不成功\n    port-range: 30500,40500 # 端口范围\n    # [可选] 国标级联在此范围内选择端口发送媒体流,\n    send-port-range: 30000,30500 # 端口范围\n\n# [根据业务需求配置]\nuser-settings:\n  # 点播/录像回放 等待超时时间,单位：毫秒\n  play-timeout: 180000\n  # [可选] 自动点播， 使用固定流地址进行播放时，如果未点播则自动进行点播, 需要rtp.enable=true\n  auto-apply-play: true\n  # 推流直播是否录制\n  record-push-live: true\n  # 国标是否录制\n  record-sip: true\n  # 国标点播 按需拉流, true：有人观看拉流，无人观看释放， false：拉起后不自动释放\n  stream-on-demand: false\n  # 是否返回Date属性，true：不返回，避免摄像头通过该参数自动校时，false：返回，摄像头可能会根据该时间校时\n  disable-date-header: false\n  # 是否开启sql日志\n  sql-log: false\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'zlm生成接口文档\'\n    # 描述\n    description: \'zlm生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '480fcdc0ebdabca5e06b84e078d1e658', '2026-04-02 17:01:01', '2026-04-02 09:01:01', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (36, 46, 'ruoyi-zlm-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  gateway:\n    prrt: 8080\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  datasource:\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n    username: root\n    password: haoxin\n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.zlm.**.domain\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n#zlm 默认服务器配置\nmedia:\n  id: hxkj_zlm\n  # [必须修改] zlm服务器的内网IP\n  ip: 192.168.2.200\n  # [必须修改] zlm服务器的http.port\n  http-port: 8092\n  http-ssl-port: 443\n  # [可选] zlm服务器的hook所使用的IP, 默认使用sip.ip\n  hook-ip: 192.168.2.200\n  # [必选选] zlm服务器的hook.admin_params=secret\n  secret: hxkj_zlm\n  #  # [可选] 录像文件存储路径\n  #  record-path: F:/zml/record\n  # [可选] 录像保存时间,单位是天\n  record-day: 3\n  # 启用多端口模式, 多端口模式使用端口区分每路流，兼容性更好。 单端口使用流的ssrc区分， 点播超时建议使用多端口测试\n  rtp:\n    # [可选] 是否启用多端口模式, 开启后会在portRange范围内选择端口用于媒体流传输\n    enable: true\n    # [可选] 在此范围内选择端口用于媒体流传输, 必须提前在zlm上配置该属性，不然自动配置此属性可能不成功\n    port-range: 30500,40500 # 端口范围\n    # [可选] 国标级联在此范围内选择端口发送媒体流,\n    send-port-range: 30000,30500 # 端口范围\n\n# [根据业务需求配置]\nuser-settings:\n  # 点播/录像回放 等待超时时间,单位：毫秒\n  play-timeout: 180000\n  # [可选] 自动点播， 使用固定流地址进行播放时，如果未点播则自动进行点播, 需要rtp.enable=true\n  auto-apply-play: true\n  # 推流直播是否录制\n  record-push-live: true\n  # 国标是否录制\n  record-sip: true\n  # 国标点播 按需拉流, true：有人观看拉流，无人观看释放， false：拉起后不自动释放\n  stream-on-demand: false\n  # 是否返回Date属性，true：不返回，避免摄像头通过该参数自动校时，false：返回，摄像头可能会根据该时间校时\n  disable-date-header: false\n  # 是否开启sql日志\n  sql-log: false\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'zlm生成接口文档\'\n    # 描述\n    description: \'zlm生成接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '79505cfeea602183cb673892632cd070', '2026-04-02 17:01:59', '2026-04-02 09:01:59', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\"}');
INSERT INTO `his_config_info` VALUES (10, 47, 'application-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot3.autoconfigure.DruidDataSourceAutoConfigure\n\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n', '7c15e6670696b957ea14279036f8023f', '2026-04-02 17:02:13', '2026-04-02 09:02:14', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos_namespace_migrate\",\"c_desc\":\"通用配置\"}');
INSERT INTO `his_config_info` VALUES (10, 48, 'application-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  autoconfigure:\n    exclude: com.alibaba.druid.spring.boot3.autoconfigure.DruidDataSourceAutoConfigure\n\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n#zlm 默认服务器配置\nmedia:\n  id: hxkj_zlm\n  # [必须修改] zlm服务器的内网IP\n  ip: 192.168.2.200\n  # [必须修改] zlm服务器的http.port\n  http-port: 8092\n  http-ssl-port: 443\n  # [可选] zlm服务器的hook所使用的IP, 默认使用sip.ip\n  hook-ip: 192.168.2.200\n  # [必选选] zlm服务器的hook.admin_params=secret\n  secret: hxkj_zlm\n  #  # [可选] 录像文件存储路径\n  #  record-path: F:/zml/record\n  # [可选] 录像保存时间,单位是天\n  record-day: 3\n  # 启用多端口模式, 多端口模式使用端口区分每路流，兼容性更好。 单端口使用流的ssrc区分， 点播超时建议使用多端口测试\n  rtp:\n    # [可选] 是否启用多端口模式, 开启后会在portRange范围内选择端口用于媒体流传输\n    enable: true\n    # [可选] 在此范围内选择端口用于媒体流传输, 必须提前在zlm上配置该属性，不然自动配置此属性可能不成功\n    port-range: 30500,40500 # 端口范围\n    # [可选] 国标级联在此范围内选择端口发送媒体流,\n    send-port-range: 30000,30500 # 端口范围\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'\n', 'e1ebf61250e0e6fb32924f8d8b4ffc41', '2026-04-07 12:06:35', '2026-04-07 04:06:35', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"通用配置\"}');
INSERT INTO `his_config_info` VALUES (17, 49, 'ruoyi-file-dev.yml', 'DEFAULT_GROUP', '', '# 本地文件上传    \nfile:\n    domain: http://127.0.0.1:9300\n    path: D:/ruoyi/uploadPath\n    prefix: /statics\n\n# FastDFS配置\nfdfs:\n  domain: http://127.0.0.1\n  soTimeout: 3000\n  connectTimeout: 2000\n  trackerList: 127.0.0.1:22122\n\n# Minio配置\nminio:\n  url: http://127.0.0.1:9000\n  accessKey: minioadmin\n  secretKey: minioadmin\n  bucketName: test\n\n  # 防盗链配置\nreferer:\n  # 防盗链开关\n  enabled: false\n  # 允许的域名列表\n  allowed-domains: localhost,127.0.0.1,ruoyi.vip,www.ruoyi.vip\n\nspring:\n  servlet:\n    multipart:\n      # 单个文件的最大大小，例如 1024MB\n      max-file-size: 1204MB\n      # 整个请求（可包含多个文件）的最大总大小，例如 100MB\n      max-request-size: 5120MB\n', '9ac57e51080c326dc778faf670c15d0b', '2026-04-07 12:06:51', '2026-04-07 04:06:52', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"文件服务\"}');
