INSERT INTO `his_config_info` VALUES (11, 53, 'ruoyi-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: 123456\n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                # 验证码处理\n                - CacheRequestBody\n                - ValidateCodeFilter\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/code/**\n              filters:\n                - StripPrefix=1\n            # 定时任务\n            - id: ruoyi-job\n              uri: lb://ruoyi-job\n              predicates:\n                - Path=/schedule/**\n              filters:\n                - StripPrefix=1\n            # 系统模块\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**\n              filters:\n                - StripPrefix=1\n            # 文件服务\n            - id: ruoyi-file\n              uri: lb://ruoyi-file\n              predicates:\n                - Path=/file/**\n              filters:\n                - StripPrefix=1\n             # 海康sdk服务\n            - id: ruoyi-haikang\n              uri: lb://ruoyi-haikang\n              predicates:\n                - Path=/haikang/**\n              filters:\n                - StripPrefix=1\n              # 泉视服务\n            - id: ruoyi-qs\n              uri: lb://ruoyi-qs\n              predicates:\n                - Path=/qs/**\n              filters:\n                - StripPrefix=1\n              # 海康isup服务\n            - id: ruoyi-haikang-isup\n              uri: lb://ruoyi-haikang-isup\n              predicates:\n                - Path=/haikangIsup/**\n              filters:\n                - StripPrefix=1\n              # 大华sdk服务\n            - id: ruoyi-dahua\n              uri: lb://ruoyi-dahua\n              predicates:\n                - Path=/dahua/**\n              filters:\n                - StripPrefix=1\n              # zlm服务\n            - id: ruoyi-zlm\n              uri: lb://ruoyi-zlm\n              predicates:\n                - Path=/zlm/**\n              filters:\n                - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n      - /zlm/index/hook/**\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', '670be169f524623d3becd1d35caaf3e2', '2026-04-09 15:02:55', '2026-04-09 07:02:55', 'nacos', '172.19.0.1', 'U', 'public', '', 'formal', '', '{\"type\":\"yaml\",\"src_user\":\"nacos\",\"c_desc\":\"网关模块\"}');
